module div_16bit(
    input [15:0] A,
    input [7:0] B,
    output reg [15:0] result,
    output reg [15:0] odd
);

    reg [15:0] a_reg, b_reg;

    always @(A or B) begin
        a_reg = A;
        b_reg = {8'b0, B};
    end

    always @(a_reg or b_reg) begin
        if (a_reg >= b_reg) begin
            result = a_reg / b_reg;
            odd = a_reg % b_reg;
        end else begin
            result = 16'b0;
            odd = a_reg;
        end
    end

endmodule
